cat > igrep/cli.py <<'PY'
"""Command-line handling, including diagnostics and editor configuration."""
from dataclasses import dataclass, field
from importlib.resources import files
import json
import os
import sys

EDITORS = 'vim neovim nvim nano code vscode code-insiders emacs emacsclient hx helix subl sublime-text micro intellij goland pycharm less fresh'.split()
VALUES = {
    'editor': EDITORS,
    'theme': ['light', 'dark'],
    'context-viewer': ['none', 'vertical', 'horizontal'],
    'sort': ['path', 'modified', 'created', 'accessed'],
    'sortr': ['path', 'modified', 'created', 'accessed'],
}
METAVARS = {
    'editor': 'EDITOR', 'custom-command': 'CUSTOM_COMMAND', 'theme': 'THEME',
    'glob': 'GLOB', 'type': 'TYPE_MATCHING', 'type-not': 'TYPE_NOT',
    'context-viewer': 'CONTEXT_VIEWER', 'sort': 'SORT_BY', 'sortr': 'SORT_BY_REVERSE',
}
SHORT = {
    'i': 'ignore-case', 'S': 'smart-case', '.': 'hidden', 'L': 'follow',
    'w': 'word-regexp', 'F': 'fixed-strings', 'U': 'multiline', 'g': 'glob',
    't': 'type', 'T': 'type-not', 'h': 'help', 'V': 'version',
}
FLAGS = ['ignore-case', 'smart-case', 'hidden', 'follow', 'word-regexp', 'fixed-strings', 'multiline', 'type-list', 'help', 'version']
NAMES = list(METAVARS) + FLAGS
REPEATED = {'glob', 'type', 'type-not'}


class ExitMessage(Exception):
    def __init__(self, text='', status=1, stdout=False):
        super().__init__(text)
        self.text, self.status, self.stdout = text, status, stdout


def label(name):
    return '--' + name + (' <' + METAVARS[name] + '>' if name in METAVARS else '')


def similarity(a, b):
    """Jaro-Winkler similarity, for friendly spelling diagnostics."""
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    radius = max(max(len(a), len(b)) // 2 - 1, 0)
    aa, bb = [False] * len(a), [False] * len(b)
    count = 0
    for i, ch in enumerate(a):
        for j in range(max(0, i - radius), min(len(b), i + radius + 1)):
            if not bb[j] and ch == b[j]:
                aa[i] = bb[j] = True
                count += 1
                break
    if not count:
        return 0.0
    ac = [c for c, found in zip(a, aa) if found]
    bc = [c for c, found in zip(b, bb) if found]
    transpositions = sum(c != d for c, d in zip(ac, bc)) / 2
    result = (count / len(a) + count / len(b) + (count - transpositions) / count) / 3
    if result > 0.7:
        prefix = 0
        for c, d in zip(a, b):
            if c != d or prefix == 4:
                break
            prefix += 1
        result += prefix * 0.1 * (1 - result)
    return result


def suggest(value, possibilities):
    best, score = None, 0.8
    for p in possibilities:
        n = similarity(value, p)
        if n > score:
            best, score = p, n
    return best


@dataclass
class Options:
    pattern: str = ''
    paths: list = field(default_factory=list)
    opts: dict = field(default_factory=dict)
    editor_program: str = 'vim'
    editor_args: list = field(default_factory=lambda: ['+{line_number}', '{file_name}'])

    def get(self, key, default=None):
        return self.opts.get(key, default)


class Parser:
    def __init__(self, argv, prog=None):
        self.argv = argv
        self.prog = prog or os.path.basename(sys.argv[0]) or 'executable'
        self.parsed = {}
        self.order = []
        self.positionals = []

    def generic_usage(self):
        return f'Usage: {self.prog} [OPTIONS] --type-list <PATTERN> [PATHS]...'

    def usage(self, names=None, required=False, extra=None, remove=None):
        names = list(self.order if names is None else names)
        if remove:
            names = [n for n in names if n not in remove]
        if extra and extra not in names:
            names.append(extra)
        has_pattern = bool(self.positionals)
        if not names and not has_pattern and not required:
            return self.generic_usage()
        use = []
        if required or not has_pattern or 'type-list' in names:
            use.append('--type-list')
        use += [label(n) for n in names if n not in ('type-list', 'help', 'version')]
        if required or not has_pattern or 'type-list' in names:
            use.append('<PATTERN>')
        else:
            use.append('<PATTERN|--type-list>')
        use.append('<PATHS>...' if len(self.positionals) > 1 else '[PATHS]...')
        return f'Usage: {self.prog} ' + ' '.join(use)

    def error(self, text, usage=None, tips=None):
        message = 'error: ' + text + '\n'
        if tips:
            message += '\n' + tips + '\n'
        if usage:
            message += '\n' + usage + '\n'
        message += "\nFor more information, try '--help'.\n"
        raise ExitMessage(message, 2)

    def unknown(self, token):
        choice = suggest(token[2:], NAMES) if token.startswith('--') else None
        if choice:
            tip = f"  tip: a similar argument exists: '--{choice}'"
            usage = self.usage(extra=choice)
        else:
            tip = f"  tip: to pass '{token}' as a value, use '-- {token}'"
            usage = self.usage()
        self.error(f"unexpected argument '{token}' found", usage, tip)

    def store(self, name, val):
        if name in self.parsed and name not in REPEATED:
            self.error(f"the argument '{label(name)}' cannot be used multiple times", self.generic_usage())
        if name in VALUES and val not in VALUES[name]:
            if val == '':
                self.missing_value(name)
            text = f"invalid value '{val}' for '{label(name)}'\n  [possible values: {', '.join(VALUES[name])}]"
            choice = suggest(val, VALUES[name])
            tip = f"  tip: a similar value exists: '{choice}'" if choice else None
            self.error(text, tips=tip)
        if name not in self.order:
            self.order.append(name)
        if name in REPEATED:
            self.parsed.setdefault(name, []).append(val)
        else:
            self.parsed[name] = val

    def missing_value(self, name):
        text = f"a value is required for '{label(name)}' but none was supplied"
        if name in VALUES:
            text += f"\n  [possible values: {', '.join(VALUES[name])}]"
        self.error(text)

    def help(self):
        text = files('igrep').joinpath('help.txt').read_text()
        text = text.replace('Usage: executable ', 'Usage: ' + self.prog + ' ')
        text = text.replace('IGREP_CUSTOM_EDITOR=]', 'IGREP_CUSTOM_EDITOR=' + os.environ.get('IGREP_CUSTOM_EDITOR', '') + ']')
        raise ExitMessage(text, 0, True)

    def parse(self):
        i, positional_mode = 0, False
        while i < len(self.argv):
            arg = self.argv[i]
            if positional_mode or arg == '-' or not arg.startswith('-'):
                self.positionals.append(arg)
                i += 1
                continue
            if arg == '--':
                positional_mode = True
                i += 1
                continue
            if arg.startswith('--'):
                raw, eq, val = arg[2:].partition('=')
                if raw not in NAMES:
                    self.unknown('--' + raw)
                tokens = [(raw, val if eq else None)]
            else:
                tokens = []
                k = 1
                while k < len(arg):
                    c = arg[k]
                    if c not in SHORT:
                        # Flags earlier in the same cluster have already been handled.
                        tokens.append((None, '-' + c))
                        break
                    name = SHORT[c]
                    if name in METAVARS:
                        val = arg[k+1:] or None
                        if val is not None and val.startswith('='):
                            val = val[1:]
                        tokens.append((name, val))
                        break
                    tokens.append((name, None))
                    k += 1
            for name, val in tokens:
                if name is None:
                    self.unknown(val)
                if name == 'help' and val is None:
                    self.help()
                if name == 'version' and val is None:
                    raise ExitMessage('igrep 1.3.0\n', 0, True)
                if name in METAVARS:
                    if val is None:
                        if i + 1 >= len(self.argv):
                            self.missing_value(name)
                        nxt = self.argv[i + 1]
                        if nxt.startswith('-') and nxt != '-':
                            key = nxt.split('=')[0]
                            valid_next = (key[2:] in NAMES if key.startswith('--') else key[1:2] in SHORT)
                            if key == '--' or valid_next:
                                self.missing_value(name)
                            self.unknown(key if key.startswith('--') else key[:2])
                        i += 1
                        val = self.argv[i]
                    self.store(name, val)
                else:
                    if val is not None:
                        self.error(f"unexpected value '{val}' for '--{name}' found; no more were expected", self.usage(extra=name))
                    self.store(name, True)
            i += 1
        if 'custom-command' not in self.parsed and 'IGREP_CUSTOM_EDITOR' in os.environ:
            self.parsed['custom-command'] = os.environ['IGREP_CUSTOM_EDITOR']
            self.order.append('custom-command')
        for a in self.order:
            if a in ('editor', 'custom-command'):
                b = 'custom-command' if a == 'editor' else 'editor'
                if b in self.parsed:
                    self.error(f"the argument '{label(a)}' cannot be used with '{label(b)}'", self.usage(required=True, remove={b}))
            if a == 'type-list' and self.positionals:
                self.error("the argument '--type-list' cannot be used with '<PATTERN>'", self.usage(required=True))
        if not self.positionals and not self.parsed.get('type-list'):
            self.error('the following required arguments were not provided:\n  --type-list\n  <PATTERN>', self.usage(required=True))
        if self.parsed.get('type-list'):
            raise ExitMessage(files('igrep').joinpath('filetypes.txt').read_text(), 0, True)
        return Options(self.positionals[0], self.positionals[1:], self.parsed)


def configure_editor(options):
    if options.get('custom-command') is not None:
        cmd = options.get('custom-command')
        pieces = cmd.split(' ')
        if len(pieces) < 2:
            reason = 'Expected program and its arguments'
        elif ' '.join(pieces[1:]).count('{file_name}') != 1:
            reason = "Expected one occurrence of '{file_name}'."
        elif ' '.join(pieces[1:]).count('{line_number}') != 1:
            reason = "Expected one occurrence of '{line_number}'."
        else:
            options.editor_program = pieces[0]
