                    raise ExitMessage(f'Error: {quoted} read from ${env}, possible variants: [{", ".join(EDITORS)}]\n\nCaused by:\n    invalid variant: {editor}\n')
                # The name of the selected editor determines its invocation.
                explicit_path = val if '/' in val else None
                break
    if editor is None:
        editor = 'vim'
    aliases = {'neovim': 'nvim', 'vscode': 'code', 'sublime-text': 'subl', 'intellij': 'idea'}
    options.editor_program = aliases.get(editor, editor)
    if editor in ('code', 'vscode', 'code-insiders'):
        options.editor_args = ['-g', '{file_name}:{line_number}']
    elif editor in ('emacs', 'emacsclient'):
        options.editor_args = ['-nw', '+{line_number}', '{file_name}']
    elif editor in ('hx', 'helix', 'subl', 'sublime-text', 'fresh'):
        options.editor_args = ['{file_name}:{line_number}']
    elif editor in ('intellij', 'goland', 'pycharm'):
        options.editor_args = ['--line', '{line_number}', '{file_name}']
    else:
        options.editor_args = ['+{line_number}', '{file_name}']
