def glob_fragment(pattern):
    """Translate a path glob into a regular expression, retaining slash rules."""
    out = ''
    i = 0
    in_alternate = False
    while i < len(pattern):
        c = pattern[i]
        if c == '\\':
            if i + 1 == len(pattern):
                raise ValueError("dangling '\\'")
            i += 1
            out += re.escape(pattern[i])
        elif c == '*':
            start = i
            while i + 1 < len(pattern) and pattern[i + 1] == '*':
                i += 1
            if i > start:
                if i + 1 < len(pattern) and pattern[i + 1] == '/':
                    out += '(?:.*/)?'
                    i += 1
                else:
                    out += '.*'
            else:
                out += '[^/]*'
        elif c == '?':
            out += '[^/]'
        elif c == '[':
            j = i + 1
            if j < len(pattern) and pattern[j] in ('!', '^'):
                j += 1
            if j < len(pattern) and pattern[j] == ']':
                j += 1
            start = j
            while j < len(pattern) and pattern[j] != ']':
                if pattern[j] == '\\' and j + 1 < len(pattern):
                    j += 1
                j += 1
            if j >= len(pattern):
                raise ValueError("unclosed character class; missing ']' ")
            stuff = pattern[i+1:j]
            for a, b in re.findall(r'(.)-(.)', stuff):
                if ord(a) > ord(b):
                    raise ValueError(f"invalid range; '{a}' > '{b}'")
            if stuff.startswith('!'):
                stuff = '^' + stuff[1:]
            elif stuff.startswith('^'):
                stuff = '^' + stuff[1:]
            out += '[' + stuff + ']'
            i = j
        elif c == '{':
            if in_alternate:
                raise ValueError('nested alternate groups are not allowed')
            in_alternate = True
            out += '(?:'
        elif c == '}' and in_alternate:
            in_alternate = False
            out += ')'
        elif c == ',' and in_alternate:
            out += '|'
        else:
            out += re.escape(c)
        i += 1
    if in_alternate:
        raise ValueError("unclosed alternate group; missing '}' (maybe escape '{' with '[{]'?)")
    return out


