    n = 48 if background else 38
    if color is None:
        return '\x1b[' + ('49m' if background else '39m')
    if isinstance(color, tuple):
        return '\x1b[' + str(n) + ';2;' + ';'.join(str(c) for c in color) + 'm'
    return f'\x1b[{n};5;{color}m'


def style_escape(style):
    fg, bg, bold = style
    return '\x1b[0m' + color_escape(fg) + color_escape(bg, True) + ('\x1b[1m' if bold else '')


class Canvas:
    def __init__(self, width, height):
        self.width, self.height = width, height
        self.rows = [[(' ', DEFAULT) for _ in range(width)] for _ in range(height)]

    def fill(self, x, y, width, height, style=DEFAULT):
        for row in range(max(0, y), min(self.height, y + height)):
            for col in range(max(0, x), min(self.width, x + width)):
                self.rows[row][col] = (' ', style)

    def put(self, x, y, text, style=DEFAULT, width=None):
        if not 0 <= y < self.height:
            return x
        end = self.width if width is None else min(self.width, x + max(0, width))
        for ch in text:
            w = char_width(ch)
            if not w:
                if unicodedata.category(ch) != 'Cc' and 0 < x <= self.width:
                    target = x - 1
                    if self.rows[y][target][0] == '' and target > 0:
                        target -= 1
                    prev, previous_style = self.rows[y][target]
                    self.rows[y][target] = (prev + ch, previous_style)
                continue
            if x + w > end:
                break
            if x >= 0:
                self.rows[y][x] = (ch, style)
                if w == 2 and x + 1 < self.width:
                    self.rows[y][x + 1] = ('', style)
            x += w
        return x

    def border(self, x, y, width, height, rounded=True, style=DEFAULT, title=None):
        if width < 1 or height < 1:
            return
        a, b, c, d = ('╭', '╮', '╰', '╯') if rounded else ('┌', '┐', '└', '┘')
        if width == 1:
            for yy in range(y, y + height):
                self.put(x, yy, '│', style)
            return
        self.put(x, y, a + '─' * (width - 2) + b, style)
        if height > 1:
            self.put(x, y + height - 1, c + '─' * (width - 2) + d, style)
        for yy in range(y + 1, y + height - 1):
            self.put(x, yy, '│', style)
            self.put(x + width - 1, yy, '│', style)
        if title:
            n = text_width(title)
            start = x + 1 + max(0, (width - 2 - n) // 2)
            self.put(start, y, title, style, max(0, x + width - 1 - start))

    def ansi(self):
        pieces = []
        current = DEFAULT
        pieces.append('\x1b[0m')
        for y, row in enumerate(self.rows):
            pieces.append(f'\x1b[{y+1};1H')
            for text, style in row:
                if text == '':
                    continue
                if style != current:
                    pieces.append(style_escape(style))
                    current = style
                pieces.append(text)
        pieces.append('\x1b[0m')
        return ''.join(pieces)


KEY_CODES = {
    '[A': 'up', '[B': 'down', '[C': 'right', '[D': 'left',
    'OA': 'up', 'OB': 'down', 'OC': 'right', 'OD': 'left',
    '[H': 'home', '[F': 'end', 'OH': 'home', 'OF': 'end',
    '[1~': 'home', '[4~': 'end', '[7~': 'home', '[8~': 'end',
    '[2~': 'insert', '[3~': 'delete', '[5~': 'pageup', '[6~': 'pagedown',
    'OP': 'f1', '[11~': 'f1', 'OQ': 'f2', 'OR': 'f3', 'OS': 'f4',
    '[12~': 'f2', '[13~': 'f3', '[14~': 'f4', '[15~': 'f5',
    '[17~': 'f6', '[18~': 'f7', '[19~': 'f8', '[20~': 'f9',
    '[21~': 'f10', '[23~': 'f11', '[24~': 'f12', '[Z': 'backtab',
}


class Terminal:
    def __init__(self):
        self.fd = sys.stdin.fileno()
        self.saved = None
        self.buffer = b''
        self.escape_time = None
        self.active = False

    def size(self):
        for fd in (sys.stdout.fileno(), self.fd):
            try:
                h, w, _, _ = struct.unpack('HHHH', fcntl.ioctl(fd, termios.TIOCGWINSZ, b'\0' * 8))
                if h and w:
                    return w, h
            except OSError:
                pass
        return 80, 24

    def write(self, text):
        try:
            sys.stdout.write(text)
            sys.stdout.flush()
        except (BrokenPipeError, OSError):
            pass

    def enter(self):
        self.saved = termios.tcgetattr(self.fd)
        tty.setraw(self.fd)
        self.active = True
        self.write('\x1b[?25l\x1b[?1000h\x1b[?1002h\x1b[?1003h\x1b[?1015h\x1b[?1006h'
                   '\x1b[?1049h\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l')

    def leave(self):
        if self.active:
            self.write('\x1b[0m\x1b[?1049l\x1b[?25h')
            self.active = False
        if self.saved is not None:
            try:
                termios.tcsetattr(self.fd, termios.TCSADRAIN, self.saved)
            except termios.error:
                pass

    def suspend(self):
        if self.saved is not None:
            termios.tcsetattr(self.fd, termios.TCSADRAIN, self.saved)
        self.write('\x1b[?25h\x1b[0m')

    def resume(self):
        tty.setraw(self.fd)
        self.write('\x1b[?25l')

    def draw(self, canvas, cursor=None):
        text = canvas.ansi()
        if cursor:
            text += f'\x1b[{cursor[1]+1};{cursor[0]+1}H\x1b[?25h'
        else:
            text += '\x1b[?25l'
        self.write(text)

    def read(self, timeout=.04):
        if select.select([self.fd], [], [], timeout)[0]:
            try:
                data = os.read(self.fd, 8192)
            except OSError:
                return [('eof', None, False)]
            if not data:
                return [('eof', None, False)]
            self.buffer += data
        result = []
        while self.buffer:
            first = self.buffer[0]
            if first == 27:
                if self.escape_time is None:
                    self.escape_time = time.monotonic()
                if len(self.buffer) == 1:
                    if time.monotonic() - self.escape_time < .045:
                        break
                    self.buffer = self.buffer[1:]
                    self.escape_time = None
                    result.append(('escape', None, False))
                    continue
                rest = self.buffer[1:]
                if rest[:1] in (b'[', b'O'):
                    m = re.match(rb'(?:\[[0-9;?<]*[ -/]*[@-~]|O.)', rest)
                    if not m:
                        if len(rest) < 25:
                            break
                        self.buffer = self.buffer[1:]
                        continue
                    code = m.group().decode('ascii', errors='ignore')
                    self.buffer = self.buffer[len(m.group())+1:]
                    self.escape_time = None
                    name = KEY_CODES.get(code)
                    if name is None and code.endswith(tuple('ABCDHF')):
                        name = KEY_CODES.get('[' + code[-1])
                    result.append((name or 'unknown', None, False))
                    continue
                # Alt combinations are distinct from an isolated Escape key.
                self.buffer = self.buffer[1:]
                self.escape_time = None
                if self.buffer and self.buffer[0] < 128:
                    value = chr(self.buffer[0])
                    self.buffer = self.buffer[1:]
                    result.append(('char', value, 'alt'))
                continue
            self.escape_time = None
            self.buffer = self.buffer[1:]
            if first == 13:
                result.append(('enter', None, False))
            elif first in (127, 8):
                result.append(('backspace', None, False))
            elif first == 9:
                result.append(('tab', None, False))
            elif first < 32:
                result.append(('char', chr(first + 96), 'ctrl'))
            elif first < 128:
                result.append(('char', chr(first), False))
            else:
                count = 2 if first < 224 else 3 if first < 240 else 4
                if len(self.buffer) < count - 1:
                    self.buffer = bytes([first]) + self.buffer
                    break
                data = bytes([first]) + self.buffer[:count-1]
                self.buffer = self.buffer[count-1:]
                result.append(('char', data.decode('utf-8', errors='replace'), False))
        return result
