    def source_styles(self, text, path):
        """Lightweight lexical highlighting for common source and data formats."""
        base = (51, 51, 51) if self.light else (192, 197, 206)
        comment = (150, 150, 150) if self.light else (101, 115, 126)
        string = (24, 54, 145) if self.light else (163, 190, 140)
        number = (0, 128, 128) if self.light else (208, 135, 112)
        keyword = (167, 29, 93) if self.light else (180, 142, 173)
        function = (0, 134, 179) if self.light else (150, 181, 180)
        constant = (0, 128, 128) if self.light else (191, 97, 106)
        colors = [base] * len(text)
        ext = os.path.splitext(path)[1].lower()
        if ext in ('.txt', '.log', ''):
            return colors
        hash_comments = ext in ('.py', '.pyi', '.rb', '.sh', '.bash', '.yaml', '.yml', '.toml', '.pl', '.r', '.conf')
        regex = r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\''
        if hash_comments:
            regex += r'|#[^\n]*'
        elif ext not in ('.json', '.md', '.markdown'):
            regex += r'|//[^\n]*|/\*[\s\S]*?\*/'
        regex += r'|\b\d+(?:\.\d+)?\b|\b[A-Za-z_]\w*\b'
        keywords = set('and as assert async await break class continue def del elif else except False finally for from global if import in is lambda None nonlocal not or pass raise return True try while with yield fn let mut pub use mod struct enum impl trait self Self match loop move const static extern where unsafe int void char bool double float switch case new null true false var function public private protected extends export default package interface type select range map chan go defer'.split())
        builtins = set('print len range str int float bool list dict set tuple open super type enumerate zip sum min max abs map filter sorted any all format'.split())
        for m in re.finditer(regex, text):
            token = m.group()
            col = base
            if token.startswith('#') or token.startswith('//') or token.startswith('/*'):
                col = comment
            elif token.startswith(('"', "'")):
                # The surrounding quotes keep the normal source foreground.
                for j in range(m.start()+1, max(m.start()+1, m.end()-1)):
                    colors[j] = string
                continue
            elif token[0].isdigit():
                col = number
            elif token in keywords:
                col = keyword
            elif token.isupper():
                col = constant
            elif token in builtins:
                col = function
            for j in range(m.start(), m.end()):
                colors[j] = col
