            if bg:
                canvas.fill(x + 1, row, w - 2, 1, (None, bg, False))
            pos = x + 1
            for j, char in enumerate(line):
                cleaned = clean_text(char, 4)
                if cleaned:
                    at = offsets[line_index] + j
                    color = colors[at] if at < len(colors) else None
                    pos = canvas.put(pos, row, cleaned, (color, bg, False), max(0, x + w - 1 - pos))
                    if pos >= x + w - 1:
                        break

    def draw_status(self, canvas):
        if self.height < 1:
            return
        y = self.height - 1
        gray = DEFAULT if self.light else ((147, 147, 147), (58, 58, 58), False)
        canvas.fill(0, y, self.width, 1, gray)
        if self.error:
            state, color, message = 'ERROR', 1, self.error
        elif self.searching:
            state, color, message = 'SEARCHING', (255, 165, 0), ''
        else:
            state, color = 'FINISHED', 2
            if self.total_matches:
                n, f = self.total_matches, self.total_files
                message = f'Found {n} match' + ('es' if n != 1 else '')
                message += f' in {f} file' + ('s' if f != 1 else '')
                message += f' ({self.filtered} filtered out).' if self.filtered else '.'
            else:
                message = 'No matches found.'
        badge_width = min(12, self.width)
        canvas.fill(0, y, badge_width, 1, (None, color, False))
        left = max(0, (badge_width - len(state) + 1) // 2)
        canvas.put(left, y, state, (0, color, True), max(0, badge_width - left))
        total = sum(len(g.matches) for g in self.groups)
        current = self.selected + 1 if total else 0
        digits = len(str(total))
        counter = f'| {current:>{digits}}/{total} '
        right_x = max(0, self.width - len(counter))
        # Two reserved cells show the most recent unrecognized/pending command.
        canvas.put(badge_width, y, ' ' + message, gray, max(0, right_x - 3 - badge_width))
        if self.key_text:
            canvas.put(max(badge_width, right_x - 3), y, self.key_text[-2:].rjust(2), gray, 2)
        canvas.put(right_x, y, counter, gray, self.width - right_x)

    def draw_help(self, canvas):
        x, y, w, h = self.help_dimensions()
        canvas.fill(x, y, w, h)
        canvas.border(x, y, w, h, rounded=False, style=(2, None, False), title=' igrep 1.3.0 ')
        visible = max(0, h - 4)
        self.help_y = min(self.help_y, max(0, len(HELP_LINES) - visible))
        self.help_x = min(self.help_x, max(0, 59 - max(0, w - 4)))
        for i, line in enumerate(HELP_LINES[self.help_y:self.help_y+visible]):
            canvas.put(x + 2, y + 2 + i, line[self.help_x:], DEFAULT, max(0, w - 4))

    def draw_pattern(self, canvas):
        w, h = max(2, self.width // 2), 3
        x, y = (self.width - w) // 2, max(0, (self.height - h) // 2)
        canvas.fill(x, y, w, h, (None, None, True))
        canvas.border(x, y, w, h, rounded=False, style=(2, None, True), title=' Regex Pattern ')
        avail = max(0, w - 4)
        if self.edit_cursor < self.edit_offset:
            self.edit_offset = self.edit_cursor
        while self.edit_offset < self.edit_cursor and text_width(self.edit_text[self.edit_offset:self.edit_cursor]) >= avail and avail:
            self.edit_offset += 1
        canvas.put(x + 2, y + 1, self.edit_text[self.edit_offset:], (None, None, True), avail)
        cursor_x = min(x + w - 2, x + 2 + text_width(self.edit_text[self.edit_offset:self.edit_cursor]))
        return cursor_x, y + 1

    def draw(self):
        canvas = Canvas(self.width, self.height)
        area = max(0, self.height - 1)
        if self.viewer == 'vertical':
            # Percentage layouts round each split to its nearest cell.
            left = (self.width * (100 - self.viewer_percent) + 50) // 100
            self.draw_results(canvas, (0, 0, left, area))
            self.draw_context(canvas, (left, 0, self.width - left, area))
        elif self.viewer == 'horizontal':
            top = (area * (100 - self.viewer_percent) + 50) // 100
            self.draw_results(canvas, (0, 0, self.width, top))
            self.draw_context(canvas, (0, top, self.width, area - top))
        else:
            self.draw_results(canvas, (0, 0, self.width, area))
        self.draw_status(canvas)
        cursor = None
        if self.popup == 'help':
            self.draw_help(canvas)
        elif self.popup == 'pattern':
            cursor = self.draw_pattern(canvas)
        self.term.draw(canvas, cursor)
        self.dirty = False

    def run(self):
        self.term.enter()
        try:
            self.start_search()
            while not self.quit:
                new_width, new_height = self.term.size()
                if (new_width, new_height) != (self.width, self.height):
                    self.width, self.height = new_width, new_height
                    self.dirty = True
                self.poll_search()
                if self.quit:
                    break
                if self.dirty:
                    self.draw()
                for key in self.term.read():
                    self.handle_key(key)
                    if self.quit:
                        break
        finally:
            self.term.leave()
        return 0
