"""Application entry point."""
import os
import sys

from .cli import ExitMessage, Parser, configure_editor
from .search import Searcher, RegexFailure, build_regex
from .ui import App


def main():
    status = 0
    try:
        options = Parser(sys.argv[1:]).parse()
        searcher = Searcher(options)
        configure_editor(options)
        if not (sys.stdin.isatty() and sys.stdout.isatty()):
            try:
                build_regex(options.pattern, options)
            except RegexFailure as error:
                sys.stderr.write(error.panic())
            raise ExitMessage('Error: Resource temporarily unavailable (os error 11)\n')
        status = App(options, searcher).run()
    except ExitMessage as error:
        stream = sys.stdout if error.stdout else sys.stderr
        stream.write(error.text)
        stream.flush()
        status = error.status
    except KeyboardInterrupt:
        status = 0
    except BrokenPipeError:
        status = 1
    except OSError as error:
        sys.stderr.write(f'Error: {error.strerror} (os error {error.errno})\n')
        status = 1
    raise SystemExit(status)
