"""Interactive results, navigation, popups, and context display."""
import os
import queue
import re
import subprocess
import sys
import threading
import time

from .search import RegexFailure, decode_file
from .terminal import Canvas, Terminal, DEFAULT, clean_text, char_width, text_width


KEYMAP = [
    ('Key(s)', 'Action'), None,
    ('q, Esc, Ctrl+c', 'Quit'), ('', ''),
    ('?, F1', 'Open/close the keymap popup'),
    ('Down, j', 'Scroll down in the keymap popup'),
    ('Up, k', 'Scroll up in the keymap popup'),
    ('Right, l', 'Scroll right in the keymap popup'),
    ('Left, h', 'Scroll left in the keymap popup'), ('', ''),
    ('Down, j', 'Select next match'), ('Up,k', 'Select previous match'),
    ('Right, l, PageDown', 'Select match in next file'),
    ('Left, h, PageUp', 'Select match in previous file'),
    ('gg, Home', 'Jump to the first match'), ('Shift-g, End', 'Jump to the last match'),
    ('Enter', 'Open current file'), ('dd, Delete', 'Filter out selected match'),
    ('dw', 'Filter out all matches in current file'),
    ('v', 'Toggle vertical context viewer'), ('s', 'Toggle horizontal context viewer'),
    ('+', 'Increase context viewer size'), ('-', 'Decrease context viewer size'),
    ('F5, /', 'Open search pattern popup'), ('n', 'Sort search results by name'),
    ('m', 'Sort search results by time modified'), ('c', 'Sort search results by time created'),
    ('a', 'Sort search results by time accessed'),
]
HELP_LINES = [('─' * 19 + '┼' + '─' * 39) if item is None else
              (item[0].ljust(19) + '│ ' + item[1].ljust(38)) for item in KEYMAP]
HELP_LINES += [' ' * 59, 'Press any key to close…'.ljust(59)]


class App:
    def __init__(self, options, searcher):
        self.options, self.searcher = options, searcher
        self.term = Terminal()
        self.groups = []
        self.selected = 0
        self.scroll = 0
        self.total_matches = self.total_files = self.filtered = 0
        self.searching = True
        self.error = None
        self.viewer = options.get('context-viewer', 'none')
        self.viewer_percent = 50
        self.light = options.get('theme', 'dark') == 'light'
        self.selection_bg = (220, 220, 220) if self.light else (58, 58, 58)
        self.popup = None
        self.help_x = self.help_y = 0
        self.edit_text = ''
        self.edit_cursor = self.edit_offset = 0
        self.key_text = ''
        self.pending_key = None
        self.quit = False
        self.mailbox = queue.Queue()
        self.generation = 0
        self.search_started = 0
        self.ready_result = None
        self.width, self.height = self.term.size()
        self.dirty = True

    def flatten(self):
        return [(g, m) for g in self.groups for m in g.matches]

    def selected_match(self):
        data = self.flatten()
        return data[min(self.selected, len(data)-1)] if data else (None, None)

    def start_search(self):
        self.generation += 1
        generation = self.generation
        self.groups = []
        self.selected = self.scroll = self.filtered = 0
        self.total_matches = self.total_files = 0
        self.searching = True
        self.error = None
        self.search_started = time.monotonic()
        self.ready_result = None
        self.dirty = True
        def worker():
            try:
                data = self.searcher.run()
                self.mailbox.put((generation, data, None))
            except RegexFailure as err:
                self.mailbox.put((generation, None, err))
            except Exception:
                self.mailbox.put((generation, [], None))
        threading.Thread(target=worker, daemon=True).start()

    def poll_search(self):
        while not self.mailbox.empty():
            generation, result, error = self.mailbox.get_nowait()
            if generation == self.generation:
                self.ready_result = result, error
        if self.ready_result and time.monotonic() - self.search_started >= .1:
            result, error = self.ready_result
            self.ready_result = None
            if error:
                self.term.write(error.panic())
                self.quit = True
                return
            self.groups = result
            self.total_matches = sum(len(g.matches) for g in self.groups)
            self.total_files = len(self.groups)
            self.searching = False
            self.selected = self.scroll = 0
            self.dirty = True

    def move(self, delta):
        count = sum(len(g.matches) for g in self.groups)
        if count:
            self.selected = min(count - 1, max(0, self.selected + delta))
        self.dirty = True

    def file_move(self, delta):
        index = 0
        for pos, group in enumerate(self.groups):
            if self.selected < index + len(group.matches):
                target = pos + delta
                if 0 <= target < len(self.groups):
                    self.selected = sum(len(g.matches) for g in self.groups[:target])
                break
            index += len(group.matches)
        self.dirty = True

    def remove(self, whole_file=False):
        start = 0
        for i, group in enumerate(self.groups):
            end = start + len(group.matches)
            if self.selected < end:
                if whole_file or len(group.matches) == 1:
                    self.filtered += len(group.matches)
                    self.groups.pop(i)
                    self.selected = max(0, start - 1)
                else:
                    group.matches.pop(self.selected - start)
                    self.filtered += 1
                    self.selected = min(self.selected, start + len(group.matches) - 1)
                break
            start = end
        self.dirty = True

    def open_editor(self):
        group, match = self.selected_match()
        if group is None:
            return
        program = self.options.editor_program
        args = [part.replace('{file_name}', group.path).replace('{line_number}', str(match.number))
                for part in self.options.editor_args]
        self.term.suspend()
        try:
            subprocess.run([program] + args, check=False)
        except (OSError, ValueError):
            self.error = f"Failed to open editor '{program}'. Is it installed?"
        finally:
            self.term.resume()
        self.dirty = True

    def begin_pattern(self):
        self.popup = 'pattern'
        self.edit_text = self.options.pattern
        self.edit_cursor = len(self.edit_text)
        self.edit_offset = 0

    def pattern_key(self, name, char, modifier):
        if name == 'escape':
            self.popup = None
        elif name == 'enter':
            self.options.pattern = self.edit_text
            self.popup = None
            self.start_search()
        elif name == 'left':
            self.edit_cursor = max(0, self.edit_cursor - 1)
        elif name == 'right':
            self.edit_cursor = min(len(self.edit_text), self.edit_cursor + 1)
        elif name == 'backspace' and self.edit_cursor:
            self.edit_text = self.edit_text[:self.edit_cursor-1] + self.edit_text[self.edit_cursor:]
            self.edit_cursor -= 1
        elif name == 'delete':
            self.edit_text = self.edit_text[:self.edit_cursor] + self.edit_text[self.edit_cursor+1:]
        elif name == 'char' and not modifier:
            self.edit_text = self.edit_text[:self.edit_cursor] + char + self.edit_text[self.edit_cursor:]
            self.edit_cursor += len(char)
        self.dirty = True

    def help_dimensions(self):
        width = max(2, min(63, self.width * 80 // 100))
        height = max(2, min(34, self.height * 80 // 100))
        return (self.width - width) // 2, (self.height - height) // 2, width, height

    def help_key(self, name, char):
        _, _, w, h = self.help_dimensions()
        if name == 'down' or char == 'j':
            self.help_y = min(max(0, len(HELP_LINES) - max(0, h - 4)), self.help_y + 1)
        elif name == 'up' or char == 'k':
            self.help_y = max(0, self.help_y - 1)
        elif name == 'right' or char == 'l':
            self.help_x = min(max(0, 59 - max(0, w - 4)), self.help_x + 1)
        elif name == 'left' or char == 'h':
            self.help_x = max(0, self.help_x - 1)
        else:
            self.popup = None
        self.dirty = True

    def handle_key(self, key):
        name, char, modifier = key
        if name == 'eof':
            self.quit = True
            return
        if self.popup == 'pattern':
            self.pattern_key(name, char, modifier)
            return
        if self.popup == 'help':
            self.help_key(name, char)
            return
        if name == 'escape' or (name == 'char' and char in ('q', 'c') and (char == 'q' or modifier == 'ctrl')):
            self.quit = True
            return
        action = char if name == 'char' else name
        if self.pending_key and name == 'char':
            action = self.pending_key + char
            self.key_text = action
            self.pending_key = None
        elif name == 'char':
            self.key_text = char
        else:
            self.key_text = ''
            self.pending_key = None
        handled = True
        if action in ('j', 'down'):
            self.move(1)
        elif action in ('k', 'up'):
            self.move(-1)
        elif action in ('l', 'right', 'pagedown'):
            self.file_move(1)
        elif action in ('h', 'left', 'pageup'):
            self.file_move(-1)
        elif action in ('home', 'gg'):
            self.selected = self.scroll = 0
        elif action in ('G', 'end'):
            self.selected = max(0, sum(len(g.matches) for g in self.groups) - 1)
        elif action in ('dd', 'delete'):
            self.remove()
        elif action == 'dw':
            self.remove(True)
        elif action == 'enter':
            self.open_editor()
        elif action == 'v':
            self.viewer = 'none' if self.viewer == 'vertical' else 'vertical'
        elif action == 's':
            self.viewer = 'none' if self.viewer == 'horizontal' else 'horizontal'
        elif action == '+':
            self.viewer_percent = min(80, self.viewer_percent + 5)
        elif action == '-':
            self.viewer_percent = max(20, self.viewer_percent - 5)
        elif action in ('?', 'f1'):
            self.popup = 'help'
            self.help_x = self.help_y = 0
        elif action in ('/', 'f5'):
            self.begin_pattern()
        elif action in ('n', 'm', 'c', 'a'):
            by = {'n': 'path', 'm': 'modified', 'c': 'created', 'a': 'accessed'}[action]
            self.searcher.reverse = not self.searcher.reverse if self.searcher.sort_by == by else False
            self.searcher.sort_by = by
            self.start_search()
        elif action in ('g', 'd'):
            self.pending_key = action
            self.key_text = action + '…'
            handled = False
        else:
            handled = False
        if handled:
            self.key_text = ''
            self.pending_key = None
        self.dirty = True

    def draw_results(self, canvas, rect):
        x, y, w, h = rect
        canvas.border(x, y, w, h)
        if w < 3 or h < 3:
            return
        inner_width, inner_height = w - 2, h - 2
        rows = []
        chosen_row = None
        chosen_first = False
        index = 0
        for group in self.groups:
            rows.append(('file', group, None, None))
            for mi, match in enumerate(group.matches):
                if index == self.selected:
                    chosen_row = len(rows)
                    chosen_first = mi == 0
                rows.append(('match', group, match, index))
                index += 1
        if chosen_row is not None:
            if chosen_row >= self.scroll + inner_height:
                self.scroll = chosen_row - inner_height + 1
            if chosen_row < self.scroll:
                self.scroll = chosen_row - (1 if chosen_first else 0)
            if chosen_first and chosen_row == self.scroll:
                self.scroll = max(0, self.scroll - 1)
        self.scroll = max(0, min(self.scroll, max(0, len(rows) - inner_height)))
        for i, (kind, group, match, idx) in enumerate(rows[self.scroll:self.scroll+inner_height]):
            yy = y + i + 1
            if kind == 'file':
                canvas.put(x + 1, yy, clean_text(group.path), (13, None, False), inner_width)
                continue
            bg = self.selection_bg if idx == self.selected else None
            if bg:
                canvas.fill(x + 1, yy, inner_width, 1, (None, bg, False))
            prefix = f' {match.number}: '
            pos = canvas.put(x + 1, yy, prefix, (2, bg, False), inner_width)
            marks = [False] * len(match.text)
            for a, b in match.spans:
                for j in range(max(0, a), min(len(marks), b)):
                    marks[j] = True
            available = x + w - 1
            for j, ch in enumerate(match.text):
                text = clean_text(ch, 2)
                if text:
                    pos = canvas.put(pos, yy, text, (1 if marks[j] else None, bg, False), max(0, available - pos))
                    if pos >= available:
                        break

    def source_styles(self, text, path):
        """Lightweight lexical highlighting for common source and data formats."""
        base = (51, 51, 51) if self.light else (192, 197, 206)
        comment = (150, 150, 150) if self.light else (101, 115, 126)
        string = (24, 54, 145) if self.light else (163, 190, 140)
        number = (0, 128, 128) if self.light else (208, 135, 112)
        keyword = (167, 29, 93) if self.light else (180, 142, 173)
        function = (0, 134, 179) if self.light else (150, 181, 180)
        constant = (0, 128, 128) if self.light else (191, 97, 106)
        colors = [base] * len(text)
        ext = os.path.splitext(path)[1].lower()
        if ext in ('.txt', '.log', ''):
            return colors
        hash_comments = ext in ('.py', '.pyi', '.rb', '.sh', '.bash', '.yaml', '.yml', '.toml', '.pl', '.r', '.conf')
        regex = r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\''
        if hash_comments:
            regex += r'|#[^\n]*'
        elif ext not in ('.json', '.md', '.markdown'):
            regex += r'|//[^\n]*|/\*[\s\S]*?\*/'
        regex += r'|\b\d+(?:\.\d+)?\b|\b[A-Za-z_]\w*\b'
        keywords = set('and as assert async await break class continue def del elif else except False finally for from global if import in is lambda None nonlocal not or pass raise return True try while with yield fn let mut pub use mod struct enum impl trait self Self match loop move const static extern where unsafe int void char bool double float switch case new null true false var function public private protected extends export default package interface type select range map chan go defer'.split())
        builtins = set('print len range str int float bool list dict set tuple open super type enumerate zip sum min max abs map filter sorted any all format'.split())
        for m in re.finditer(regex, text):
            token = m.group()
            col = base
            if token.startswith('#') or token.startswith('//') or token.startswith('/*'):
                col = comment
            elif token.startswith(('"', "'")):
                # The surrounding quotes keep the normal source foreground.
                for j in range(m.start()+1, max(m.start()+1, m.end()-1)):
                    colors[j] = string
                continue
            elif token[0].isdigit():
                col = number
            elif token in keywords:
                col = keyword
            elif token.isupper():
                col = constant
            elif token in builtins:
                col = function
            for j in range(m.start(), m.end()):
                colors[j] = col
        return colors

    def draw_context(self, canvas, rect):
        x, y, w, h = rect
        canvas.border(x, y, w, h)
        group, match = self.selected_match()
        if group is None or w < 3 or h < 3:
            return
        text = group.contents
        try:
            with open(group.path, 'rb') as stream:
                fresh = decode_file(stream.read())
                if fresh is not None:
                    text = fresh
        except OSError:
            pass
        lines = text.split('\n')
        start = max(0, match.number - 1 - h // 2)
        colors = self.source_styles(text, group.path)
        offsets = [0]
        for line in lines:
            offsets.append(offsets[-1] + len(line) + 1)
        for i, line in enumerate(lines[start:start+h-2]):
            row = y + i + 1
            line_index = start + i
            bg = self.selection_bg if line_index + 1 == match.number else None
            if bg:
                canvas.fill(x + 1, row, w - 2, 1, (None, bg, False))
            pos = x + 1
            for j, char in enumerate(line):
                cleaned = clean_text(char, 4)
                if cleaned:
                    at = offsets[line_index] + j
                    color = colors[at] if at < len(colors) else None
                    pos = canvas.put(pos, row, cleaned, (color, bg, False), max(0, x + w - 1 - pos))
                    if pos >= x + w - 1:
                        break

    def draw_status(self, canvas):
        if self.height < 1:
            return
        y = self.height - 1
        gray = DEFAULT if self.light else ((147, 147, 147), (58, 58, 58), False)
        canvas.fill(0, y, self.width, 1, gray)
        if self.error:
            state, color, message = 'ERROR', 1, self.error
        elif self.searching:
            state, color, message = 'SEARCHING', (255, 165, 0), ''
        else:
            state, color = 'FINISHED', 2
            if self.total_matches:
                n, f = self.total_matches, self.total_files
                message = f'Found {n} match' + ('es' if n != 1 else '')
                message += f' in {f} file' + ('s' if f != 1 else '')
                message += f' ({self.filtered} filtered out).' if self.filtered else '.'
            else:
                message = 'No matches found.'
        badge_width = min(12, self.width)
        canvas.fill(0, y, badge_width, 1, (None, color, False))
        left = max(0, (badge_width - len(state) + 1) // 2)
        canvas.put(left, y, state, (0, color, True), max(0, badge_width - left))
        total = sum(len(g.matches) for g in self.groups)
        current = self.selected + 1 if total else 0
        digits = len(str(total))
        counter = f'| {current:>{digits}}/{total} '
        right_x = max(0, self.width - len(counter))
        # Two reserved cells show the most recent unrecognized/pending command.
        canvas.put(badge_width, y, ' ' + message, gray, max(0, right_x - 3 - badge_width))
        if self.key_text:
            canvas.put(max(badge_width, right_x - 3), y, self.key_text[-2:].rjust(2), gray, 2)
        canvas.put(right_x, y, counter, gray, self.width - right_x)

    def draw_help(self, canvas):
        x, y, w, h = self.help_dimensions()
        canvas.fill(x, y, w, h)
        canvas.border(x, y, w, h, rounded=False, style=(2, None, False), title=' igrep 1.3.0 ')
        visible = max(0, h - 4)
        self.help_y = min(self.help_y, max(0, len(HELP_LINES) - visible))
        self.help_x = min(self.help_x, max(0, 59 - max(0, w - 4)))
        for i, line in enumerate(HELP_LINES[self.help_y:self.help_y+visible]):
            canvas.put(x + 2, y + 2 + i, line[self.help_x:], DEFAULT, max(0, w - 4))

    def draw_pattern(self, canvas):
        w, h = max(2, self.width // 2), 3
        x, y = (self.width - w) // 2, max(0, (self.height - h) // 2)
        canvas.fill(x, y, w, h, (None, None, True))
        canvas.border(x, y, w, h, rounded=False, style=(2, None, True), title=' Regex Pattern ')
        avail = max(0, w - 4)
        if self.edit_cursor < self.edit_offset:
            self.edit_offset = self.edit_cursor
        while self.edit_offset < self.edit_cursor and text_width(self.edit_text[self.edit_offset:self.edit_cursor]) >= avail and avail:
            self.edit_offset += 1
        canvas.put(x + 2, y + 1, self.edit_text[self.edit_offset:], (None, None, True), avail)
        cursor_x = min(x + w - 2, x + 2 + text_width(self.edit_text[self.edit_offset:self.edit_cursor]))
        return cursor_x, y + 1

    def draw(self):
        canvas = Canvas(self.width, self.height)
        area = max(0, self.height - 1)
        if self.viewer == 'vertical':
            # Percentage layouts round each split to its nearest cell.
            left = (self.width * (100 - self.viewer_percent) + 50) // 100
            self.draw_results(canvas, (0, 0, left, area))
            self.draw_context(canvas, (left, 0, self.width - left, area))
        elif self.viewer == 'horizontal':
            top = (area * (100 - self.viewer_percent) + 50) // 100
            self.draw_results(canvas, (0, 0, self.width, top))
            self.draw_context(canvas, (0, top, self.width, area - top))
        else:
            self.draw_results(canvas, (0, 0, self.width, area))
        self.draw_status(canvas)
        cursor = None
        if self.popup == 'help':
            self.draw_help(canvas)
        elif self.popup == 'pattern':
            cursor = self.draw_pattern(canvas)
        self.term.draw(canvas, cursor)
        self.dirty = False

    def run(self):
        self.term.enter()
        try:
            self.start_search()
            while not self.quit:
                new_width, new_height = self.term.size()
                if (new_width, new_height) != (self.width, self.height):
                    self.width, self.height = new_width, new_height
                    self.dirty = True
                self.poll_search()
                if self.quit:
                    break
                if self.dirty:
                    self.draw()
                for key in self.term.read():
                    self.handle_key(key)
                    if self.quit:
                        break
        finally:
            self.term.leave()
        return 0
